    public static List<AnimationController.AnimClip> LoadAll()
    {
        return new List<AnimationController.AnimClip>
        {
            Decode(IdleBytes,    "Idle",    6f, true),
            Decode(ClickedBytes, "Clicked", 8f, true),
            Decode(DragBytes,    "Drag",    8f, true),
        };
    }

    private static AnimationController.AnimClip Decode(
        byte[] png, string name, float fps, bool loop)
    {
        var tex = new Texture2D(W * N, H, TextureFormat.RGBA32, false);
        tex.LoadImage(png);
        tex.filterMode = FilterMode.Point;
        var frames = new Sprite[N];
        for (int i = 0; i < N; i++)
            frames[i] = Sprite.Create(tex, new Rect(i * W, 0, W, H),
                                      new Vector2(0.5f, 0.5f), PPU);
        return new AnimationController.AnimClip
            { name = name, frames = frames, fps = fps, loop = loop };
    }
}
